import sys

a, c, e = map(int, sys.stdin.read().split())
# tent shapes as (committee members, non-on-call engineers) inside one tent
shapes = [(3, 0), (2, 1), (1, 2), (0, 1), (0, 2), (0, 3)]
seen = {(0, 0)}
frontier = [(0, 0)]
tents = 0
while (c, e) not in seen and frontier:
    nxt = []
    for x, y in frontier:
        for dx, dy in shapes:
            s = (x + dx, y + dy)
            if s[0] <= c and s[1] <= e and s not in seen:
                seen.add(s)
                nxt.append(s)
    frontier = nxt
    tents += 1
    if (c, e) in seen:
        break
print(a + tents if (c, e) in seen else -1)

